class Solution:
    def canSeePersonsCount(self, heights: List[int]) -> List[int]:
        n = len(heights)
        ans = [0] * n
        for i in range(n):
            tallest = 0
            for j in range(i + 1, n):
                if tallest >= heights[i]:
                    break
                if heights[j] > tallest:
                    ans[i] += 1
                    tallest = heights[j]
        return ans

